@@ -407,9 +407,13 @@ pcapng_process_darwin_legacy_block(wtap *wth, section_info_t *section_info _U_,
     return true;
 }

+/*
+ * The Darwin options are integers in the byte order of the section, like
+ * the standard ones; swap them if that is not the byte order of this host.
+ */
 static bool
-pcapng_parse_darwin_legacy_uint32(wtap_block_t block, unsigned option_code,
-    unsigned option_length, const uint8_t* option_content,
+pcapng_parse_darwin_legacy_uint32(wtap_block_t block, bool byte_swapped,
+    unsigned option_code, unsigned option_length, const uint8_t* option_content,
     int* err, char** err_info)
 {
     uint32_t uint32;
@@ -422,18 +426,21 @@ pcapng_parse_darwin_legacy_uint32(wtap_block_t block, unsigned option_code,
     }

     memcpy(&uint32, option_content, sizeof(uint32_t));
+    if (byte_swapped)
+        uint32 = GUINT32_SWAP_LE_BE(uint32);
     wtap_block_add_uint32_option(block, option_code, uint32);

-    ws_noisy("Processed integer option 0x%08x (len: %u) == %d", option_code, option_length, *(int32_t*)option_content);
+    ws_noisy("Processed integer option 0x%08x (len: %u) == %u", option_code, option_length, uint32);
     return true;
 }

 static bool
-pcapng_parse_darwin_legacy_uint16(wtap_block_t block, unsigned option_code,
-    unsigned option_length, const uint8_t* option_content,
+pcapng_parse_darwin_legacy_uint16(wtap_block_t block, bool byte_swapped,
+    unsigned option_code, unsigned option_length, const uint8_t* option_content,
     int* err, char** err_info)
 {
-    uint32_t uint32;
+    uint16_t uint16;
+
     if (option_length != 2) {
         *err = WTAP_ERR_BAD_FILE;
         *err_info = ws_strdup_printf("pcapng: Darwin option 0x%hx length expected %u, actual %u",
@@ -441,87 +448,86 @@ pcapng_parse_darwin_legacy_uint16(wtap_block_t block, unsigned option_code,
         return false;
     }

-    /* NOTE: Internally, the 16-bit options are stored as 32-bit.
-     * Because of that, we are using uint32_t as the option length,
-     * and not the real option length.
-     */
-    memcpy(&uint32, option_content, sizeof(uint32_t));
-    wtap_block_add_uint32_option(block, option_code, uint32);
+    memcpy(&uint16, option_content, sizeof(uint16_t));
+    if (byte_swapped)
+        uint16 = GUINT16_SWAP_LE_BE(uint16);
+    /* Internally, the 16-bit options are stored as 32-bit. */
+    wtap_block_add_uint32_option(block, option_code, uint16);

-    ws_noisy("Processed integer option 0x%08x (len: %u) == %d", option_code, option_length, *(int32_t*)option_content);
+    ws_noisy("Processed integer option 0x%08x (len: %u) == %u", option_code, option_length, uint16);
     return true;
 }

